const TIME_LIMIT: int = 1220;
const OPENING_BUFFER: int = 120;
const TH18_RICE: int = 480;

// Source 495-497 / 556-558: ANIM birth stage omitted by policy;
// its -4*velocity displacement is retained in emit_ring below.
// ANGLE_ACCEL: r=0, s=+/-0.010471975rad/frame (~0.6deg), for 120 ticks.
xformdef TURN(omega: angle) {
    @120 set_ang_vel(omega);
    set_ang_vel(0deg);
}

sub emit_ring(count: int, omega: angle) {
    var x: fx = $self_x;
    var y: fx = $self_y;
    // etAim=2: aim once from unshifted descriptor origin, not per bullet.
    var aim: angle = 90deg;
    if $player_x != x || $player_y != y {
        aim = atan2($player_y-y, $player_x-x);
    }
    // Source 512/563: one RANDRAD read per wave, full [-pi,pi) range.
    var alpha: int = rand(65536)-32768;
    for i in 0..count {
        var a: angle = ((aim as int)+alpha+(i*65536)/count) as angle;
        // etDist 16 minus ANIM's 4*1.8 = 8.8px along each actual angle.
        _ = fire(TH18_RICE, 4, x+8.8fx*cos(a), y+8.8fx*sin(a),
                 1.8fx, a, TURN(omega), none);
    }
}

async sub shooting(omega: angle, stagger: int) {
    var rank: int = global(GVAR_RANK);
    var count: int = 20;
    var waves: int = 10;
    var period: int = 60;
    var delay: int = 30;
    if rank > 0 {
        waves = 20;
        period = 30;
        delay = 15;
        count = 40;
    }
    if rank == 2 { count = 55; }
    if rank == 3 { count = 65; }
    // Source 474-493 / 535-554: N=20/40/55/65, M=1.
    // delta=30/30/20/15deg only offsets layer q; q=0 makes it inert.
    // etSpeed(1.8,1.5) uses 1.8 only for this single layer.
    // Source local A=1.963495 is never read; B-- gives exactly waves shots.
    if stagger != 0 { wait(delay); }
    for wave in 0..waves {
        emit_ring(count, omega);
        wait(period);
    }
}

async sub source_enemy() {
    set_invuln(65535);
    // Source 450-451; ordinary circles per rules-update.md.
    set_hurtbox(16fx);
    set_hitbox(12fx);
    // 452-454: down at 2, then quadratic-in velocity interpolation to zero.
    move_vel(0, 90deg, 2fx, EASE_LINEAR);
    move_vel(80, 90deg, 0fx, EASE_QUAD_IN);
    wait(80);
    // 455-456: both tasks keep this enemy owner, with independent locals.
    spawn shooting(109 as angle, 1);
    spawn shooting((-109) as angle, 0);
    // 457-459: retain the second zero-speed interpolation and all 500 frames.
    move_vel(80, 90deg, 0fx, EASE_QUAD_IN);
    wait(500);
    move_vel(80, 90deg, -1.4fx, EASE_QUAD_IN);
    // 460-464: original enemy task never returns; natural offscreen cleanup.
    loop { wait(1000); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // MainSub05:1006; relative to given parent FINAL=(0,0), no mirror.
    // Drop/score/ANM and 573/574 reward configuration omitted by policy.
    _ = spawn_enemy(0fx, -32fx, 8000, 0, 0, 0, source_enemy);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
